func overlongLine(delta int) io.Reader {
	prefix := `[{"name":"cpu","timestamp":2000,"value":9},`
	return io.MultiReader(
		strings.NewReader(prefix),
		&repeatReader{b: ' ', n: maxIngestLineBytes + delta - len(prefix)},
	)
}

